  return psql('SELECT (SELECT count(*) FROM frame), (SELECT count(*) FROM frame_version), (SELECT count(*) FROM import_jobs), (SELECT count(*) FROM import_row_errors)');
}

function inventoryFingerprint() {
  return psql(`SELECT md5(string_agg(to_jsonb(v)::text, ',' ORDER BY frame_id, version_id))
    FROM frame_version v`);
}

async function summary(page, job, state, counts) {
  const region = page.getByRole('region', { name: 'Import job' });
  await region.locator('.job-id').getByText(job, { exact: true }).waitFor();
  await region.getByText(state, { exact: true }).waitFor({ timeout: 55000 });
  const actual = Object.fromEntries(await region.locator('.counts > div').evaluateAll(
    (nodes) => nodes.map((node) => [node.querySelector('dt').textContent, Number(node.querySelector('dd').textContent)]),
  ));
  assert.deepEqual(Object.values(actual), counts);
  const db = psql(`SELECT status, import_mode, rows_read, rows_applied, rows_unchanged, rows_rejected, (object_version_id IS NOT NULL), (workflow_started_at IS NOT NULL)
    FROM import_jobs WHERE job_id='${job}'`);
  assert.equal(db, [state.toUpperCase().replaceAll(' ', '_'), 'DELTA', ...counts, 't', 't'].join('|'));
  console.log(job, state, JSON.stringify(actual), '(matches PostgreSQL)');
}

async function upload(page, path, state, counts) {
  await page.getByLabel('Inventory CSV').setInputFiles(path);
  const putResponse = page.waitForResponse((response) => response.request().method() === 'PUT'
    && new URL(response.url()).port === '14566', { timeout: 15000 });
  await page.getByRole('button', { name: 'Upload CSV' }).click();
  const response = await putResponse;
  assert.equal(response.status(), 200);
  const objectVersion = (await response.allHeaders())['x-amz-version-id'];
  assert.ok(objectVersion);
  const job = await page.locator('.job-id').textContent();
  assert.match(job, /^[0-9a-f-]{36}$/);
  await summary(page, job, state, counts);
  assert.equal(psql(`SELECT object_version_id FROM import_jobs WHERE job_id='${job}'`), objectVersion);
  return job;
}

