enum ImportMode {
  IMPORT_MODE_UNSPECIFIED = 0;
  DELTA = 1;
  FULL_SNAPSHOT = 2;
}

enum ImportJobStatus {
  IMPORT_JOB_STATUS_UNSPECIFIED = 0;
  AWAITING_UPLOAD = 1;
  PENDING = 2;
  RUNNING = 3;
  COMPLETED = 4;
  COMPLETED_WITH_ERRORS = 5;
  FAILED = 6;
  EXPIRED = 7;
}

message CreateImportJobRequest {
  // Defaults to DELTA. FULL_SNAPSHOT is reserved until snapshot validation ships.
  ImportMode mode = 1;
  bool force_overwrite = 2;
}

message CreateImportJobResponse {
  ImportJob job = 1;
  string upload_url = 2;
  // Send these headers with the PUT. The browser supplies Host.
  map<string, string> upload_headers = 3;
}

message GetImportJobRequest {
  string job_id = 1;
