  ImportJobStatus status = 3;
  bool force_overwrite = 4;
  google.protobuf.Timestamp created_at = 5;
  google.protobuf.Timestamp upload_expires_at = 6;
  google.protobuf.Timestamp finished_at = 7;
  int32 rows_read = 8;
  int32 rows_applied = 9;
  int32 rows_unchanged = 10;
  int32 rows_rejected = 11;
  int32 frames_retired = 12;
  optional string failure_code = 13;
}

message ListImportRowErrorsRequest {
  string job_id = 1;
