  int32 row_number = 1;
  string code = 2;
  optional string frame_id = 3;
  string detail = 4;
}

message ListImportRowErrorsResponse {
  repeated ImportRowError items = 1;
  int32 page = 2;
  int32 size = 3;
  bool has_next = 4;
}

